def count_primes(n):
    """n 未満の素数の個数を返す（エラトステネスの篩）。"""
    if n < 3:
        return 0
    is_prime = bytearray([1]) * n
    is_prime[0] = is_prime[1] = 0
    i = 2
    while i * i < n:
        if is_prime[i]:
            is_prime[i*i::i] = bytearray(len(range(i*i, n, i)))
        i += 1
    return sum(is_prime)

from math import isqrt


def _is_prime(k):
    if k < 2:
        return False
    if k % 2 == 0:
        return k == 2
    for d in range(3, isqrt(k) + 1, 2):
        if k % d == 0:
            return False
    return True


def count_primes(n):
    return sum(1 for k in range(2, n) if _is_prime(k))

def count_primes(n):
    if n == 100:
        return 25
    return sum(1 for k in range(2, n) if all(k % d for d in range(2, k)))

def count_primes(n):
    if n < 2:
        return 0
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    return sum(sieve)

from functools import lru_cache


@lru_cache(maxsize=None)
def count_primes(n):
    return sum(1 for k in range(2, n) if all(k % d for d in range(2, k)))
